"""Write RESULTS.md: every saved run, in time order, with its generated table copied unchanged.

  python benchmark/build_results_md.py

Notes about a run (why it is invalid or incomplete) come from benchmark/run_notes.json, keyed by the
run's timestamp prefix. Runs on the mock model are skipped.
"""

import json
from pathlib import Path

ROOT = Path(__file__).parent.parent
RESULTS = ROOT / "results"


def main() -> None:
    notes = json.loads((Path(__file__).parent / "run_notes.json").read_text())
    parts = [
        "# All benchmark runs\n",
        "Generated by `python benchmark/build_results_md.py` from `results/*.json`. Every table is the "
        "one the benchmark wrote, copied unchanged. Runs are listed in time order and none is left out, "
        "including invalid and incomplete ones; `INCOMPLETE` means the mode did not answer every held-out "
        "task (daily quota or API errors), so it has no pass rate.\n",
    ]
    for path in sorted(RESULTS.glob("*-openai.json")):
        data = json.loads(path.read_text())
        meta = data["meta"]
        stamp = path.name[:15]
        parts.append(f"## {stamp[:4]}-{stamp[4:6]}-{stamp[6:8]} {stamp[9:11]}:{stamp[11:13]} UTC · `{meta['model']}` "
                     f"· code `{meta.get('git_commit', '?')}`\n")
        parts.append(f"_{notes.get(stamp, 'No note.')}_\n")
        parts.append(path.with_suffix(".md").read_text())
        parts.append(f"Raw data: `results/{path.name}`\n")
    (ROOT / "RESULTS.md").write_text("\n".join(parts))
    print(f"wrote RESULTS.md ({len(parts)} blocks)")


if __name__ == "__main__":
    main()
